CREATE OR REPLACE FUNCTION public.cellar_dig_reason(p_world uuid, p_uid uuid, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_x int := (p_target->>'x')::int; v_y int := (p_target->>'y')::int;
        v_b int; v_dug int; v_gap text; v_shallow int; v_h int;
begin
  v_b := building_at(p_world, v_x, v_y);
  if v_b is null then return 'Cellars go under a building.'; end if;
  -- The ground under a deck on piers is not dug while the building stands (`piers.ts`).
  if on_piers(p_world, v_x, v_y) then return 'Not under a deck on piers.'; end if;
  if not cellar_stands_in(p_world, p_uid, v_b) then
    return 'Stand inside that building: ground floor or cellar.';
  end if;
  v_dug := coalesce((cellar_at(p_world, v_x, v_y)).dug, 0);
  if v_dug >= cellar_depth() then
    return 'Cellar fully dug: ' || metres(cellar_depth()) || ' m down.';
  end if;
  -- A building standing over it, and closed in: there is no ground floor to dig under until there is.
  v_gap := level_gap(p_world, v_b, 0, p_uid);
  if v_gap is not null then return v_gap; end if;
  if (slab_at(p_world, v_x, v_y)).id is not null then return 'Not under a poured foundation.'; end if;
  v_shallow := cellar_shallowest(p_world, v_x, v_y);
  if v_dug = 0 and v_shallow < cellar_least_soil() then
    return 'Rock ' || metres(v_shallow) || ' m under the ground floor at the shallowest corner; needs '
      || metres(cellar_least_soil()) || ' m of soil at every corner.';
  end if;
  v_h := land_height(p_world, v_x, v_y);
  if v_h - cellar_depth() < 0 then
    return 'Ground floor at ' || metres(v_h) || ' m: needs ' || metres(cellar_depth())
      || ' m above sea level for a ' || metres(cellar_depth()) || ' m deep cellar.';
  end if;
  return null;
end $function$
